import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9eb7b2);scene.fog=new THREE.Fog(0x9eb7b2,48,150);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,240);
const renderer=new THREE.WebGLRenderer({antialias:false,alpha:false});renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.setPixelRatio(.85);renderer.setSize(innerWidth*.85,innerHeight*.85,false);$('#world').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xd9e8e3,0x514538,2.1));const sun=new THREE.DirectionalLight(0xffdfaa,3.2);sun.position.set(-25,38,22);scene.add(sun);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;
const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness,flatShading:true});
const mats={ground:mat(0x777d61),path:mat(0xa58c69),stone:mat(0x676963),wood:mat(0x674a36),leaf:mat(0x4e6850),leaf2:mat(0x74815a),gold:mat(0xe4b56d),dark:mat(0x293236),skin:mat(0xe0b28a),cloth:mat(0x365966),red:mat(0xa7463d),white:mat(0xe2d6bc),black:mat(0x29272b),slime:mat(0x8cae70),purple:mat(0x8a596c)};
function mesh(geo,material,x=0,y=0,z=0,parent=scene){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,x,y,z,w,h,d,material){return mesh(new THREE.BoxGeometry(w,h,d),material,x,y,z,parent)}
function makeTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);mesh(new THREE.CylinderGeometry(.25,.42,2.5,5),mats.wood,0,1.25,0,g);mesh(new THREE.ConeGeometry(1.7,3.1,5),mats.leaf,0,3.1,0,g);mesh(new THREE.ConeGeometry(1.3,2.4,5),mats.leaf2,0,4.2,0,g)}
function makeRock(x,y,z,s=1,color=mats.stone){const r=mesh(new THREE.DodecahedronGeometry(s,0),color,x,y,z);r.rotation.set(Math.random(),Math.random(),Math.random());return r}
// broad, hand-built low-poly frontier
const terrain=mesh(new THREE.PlaneGeometry(220,230,1,1),mats.ground,0,-.18,-30);terrain.rotation.x=-Math.PI/2;terrain.receiveShadow=true;
const water=mesh(new THREE.PlaneGeometry(500,500),mat(0x597c81,.6),0,-1.45,-35);water.rotation.x=-Math.PI/2;
// wandering ochre road
const road=mesh(new THREE.PlaneGeometry(7,150),mats.path,0,-.06,-36);road.rotation.x=-Math.PI/2;road.rotation.z=.045;
for(let i=0;i<36;i++){const z=-100+i*4.8;makeRock(Math.sin(i*.72)*5,-.05,z,.22+(i%3)*.07,i%2?mats.path:mats.stone)}
for(let i=0;i<38;i++){let x,z;if(i<20){x=(Math.random()<.5?-1:1)*(9+Math.random()*18);z=-8-Math.random()*74}else{x=-45+Math.random()*90;z=-78-Math.random()*32}makeTree(x,z,.8+Math.random()*.6)}
// distant basalt teeth and a ruined crown
for(let i=0;i<13;i++){const x=-67+i*11;const h=17+Math.random()*24;mesh(new THREE.ConeGeometry(8+Math.random()*7,h,5),mat(i%2?0x667376:0x75837d),x,h/2-1,-112)}
function buildKeep(){const x=0,z=-83;box(scene,x,5,z,16,10,9,mat(0x55565a));box(scene,x,10,z,20,1,12,mat(0x4b4b50));for(const sx of [-8,8]){box(scene,x+sx,8,z,4,16,5,mat(0x4c4a4e));mesh(new THREE.ConeGeometry(3,5,4),mats.red,x+sx,18,z)}box(scene,x,14,z-2,5,11,4,mat(0x39383f));mesh(new THREE.ConeGeometry(4,7,4),mat(0x39383f),0,23,z-2).rotation.y=Math.PI/4;const glow=mesh(new THREE.OctahedronGeometry(1.3),mat(0xda564d),0,10,z-4);glow.material.emissive=new THREE.Color(0xc73532);glow.material.emissiveIntensity=1.4}
buildKeep();
function makeActor({name,type='npc',x=0,z=0,cloth=mats.cloth,skin=mats.skin,scale=1}){const root=new THREE.Group();root.position.set(x,0,z);root.scale.setScalar(scale);scene.add(root);const model=new THREE.Group();root.add(model);const torso=mesh(new THREE.BoxGeometry(.78,1.05,.44),cloth,0,1.25,0,model);const head=mesh(new THREE.BoxGeometry(.53,.57,.51),skin,0,2.1,0,model);mesh(new THREE.BoxGeometry(.08,.08,.04),mats.black,-.12,2.14,.27,model);mesh(new THREE.BoxGeometry(.08,.08,.04),mats.black,.12,2.14,.27,model);mesh(new THREE.BoxGeometry(.6,.15,.57),type==='enemy'?mats.red:mats.gold,0,2.4,0,model);const arms=[];for(const s of [-1,1]){const arm=new THREE.Group();arm.position.set(s*.48,1.62,0);model.add(arm);mesh(new THREE.BoxGeometry(.23,.72,.25),cloth,0,-.32,0,arm);arms.push(arm);const leg=new THREE.Group();leg.position.set(s*.21,.78,0);model.add(leg);mesh(new THREE.BoxGeometry(.27,.75,.3),mats.dark,0,-.25,0,leg);if(!root.userData.legs)root.userData.legs=[];root.userData.legs.push(leg)}if(type==='player'){const cape=mesh(new THREE.BoxGeometry(.7,.95,.12),mats.red,0,1.25,-.32,model);cape.rotation.x=-.08}else if(type==='enemy'){mesh(new THREE.ConeGeometry(.15,.55,4),mats.red,-.22,2.62,0,model);mesh(new THREE.ConeGeometry(.15,.55,4),mats.red,.22,2.62,0,model)}const marker=mesh(new THREE.ConeGeometry(.12,.22,4),mats.gold,0,3.05,0,root);marker.rotation.x=Math.PI;marker.visible=false;root.userData={...(root.userData||{}),name,type,model,head,torso,arms,marker,phase:Math.random()*5,hp:3,maxHp:3,alive:true,cooldown:Math.random()*2,hit:0};return root}
const player=makeActor({name:'Hero',type:'player',x:0,z:5,cloth:mats.cloth});player.userData.marker.visible=false;
const keeper=makeActor({name:'Keeper',x:-2,z:-1,cloth:mat(0x927c58)});const scout=makeActor({name:'Scout',x:7,z:-9,cloth:mat(0x647b61),scale:.95});
const enemies=[];function spawnEnemy(x,z,boss=false){const e=makeActor({name:boss?'Demon King':'Ashling',type:'enemy',x,z,cloth:boss?mat(0x392c42):mats.slime,skin:boss?mat(0x985253):mat(0xa0c577),scale:boss?2.45:.9});e.userData.boss=boss;e.userData.hp=boss?12:3;e.userData.maxHp=e.userData.hp;e.userData.cooldown=1.5+Math.random()*2;enemies.push(e);return e}
const spawnPositions=[[-13,-18],[11,-24],[-6,-35],[18,-44],[-17,-51],[8,-60]];spawnPositions.forEach(([x,z])=>spawnEnemy(x,z));
const hero={name:'Rook',gender:'wanderer',skin:0xe0b28a,cloth:0x365966,hair:0xe4b56d,scale:1,level:1,xp:0,hp:100,maxHp:100,stamina:100,attack:1,defense:0,potions:2,coins:12,inventory:{'Field herbs':1,'Iron scrap':1,'Ashling core':0,'Sunstone':0},equipped:'Wayfarer blade'};
let state='menu',cameraAngle=0,keys={},last=performance.now(),time=0,quest=null,bossUnlocked=false,boss=null,interactTarget=null,modalTab='inventory',settings={quality:'medium',resolution:.85,volume:65,sensitivity:5};
// title composition
camera.position.set(13,10,19);camera.lookAt(0,2,-9);
const playerGlow=new THREE.PointLight(0xf4be72,22,18);playerGlow.position.set(-5,5,7);scene.add(playerGlow);
const editorModels=[player];
function refreshHero(){const u=player.userData;player.scale.setScalar(hero.scale);u.torso.material=mat(hero.cloth);u.head.material=mat(hero.skin);u.model.children.filter(c=>c.material===mats.red).forEach(c=>c.material=mat(hero.hair));u.model.children.forEach(c=>{if(c.geometry?.type==='BoxGeometry'&&Math.abs(c.position.x)>.4&&c.position.y>1)c.material=mat(hero.cloth)});$('#heroName').value=hero.name;$('#hudName').textContent=hero.name.toUpperCase();$('#classText').textContent=hero.gender.toUpperCase()}

