function refreshHero(){const u=player.userData;player.scale.setScalar(hero.scale);u.torso.material=mat(hero.cloth);u.head.material=mat(hero.skin);u.model.children.filter(c=>c.material===mats.red).forEach(c=>c.material=mat(hero.hair));u.model.children.forEach(c=>{if(c.geometry?.type==='BoxGeometry'&&Math.abs(c.position.x)>.4&&c.position.y>1)c.material=mat(hero.cloth)});$('#heroName').value=hero.name;$('#hudName').textContent=hero.name.toUpperCase();$('#classText').textContent=hero.gender.toUpperCase()}
const skinColors=[0xf3cfad,0xe0b28a,0xb97854,0x81543e],clothColors=[0x365966,0x6e453c,0x59644b,0x3e4261,0x987342],hairColors=[0xe4b56d,0x29272b,0x923f32,0xcac1aa,0x5b4538];
function swatches(id,colors,key){const el=$('#'+id);colors.forEach((c,i)=>{const b=document.createElement('button');b.className='swatch'+(i===0?' selected':'');b.style.background='#'+c.toString(16).padStart(6,'0');b.setAttribute('aria-label','Color '+(i+1));b.onclick=()=>{el.querySelectorAll('.swatch').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');hero[key]=c;refreshHero()};el.appendChild(b)})}swatches('skinSwatches',skinColors,'skin');swatches('clothSwatches',clothColors,'cloth');swatches('hairSwatches',hairColors,'hair');
$$('.segmented button').forEach(b=>b.onclick=()=>{$$('.segmented button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');hero.gender=b.dataset.gender;$('#classText').textContent=hero.gender.toUpperCase()});$('#heroName').oninput=e=>{hero.name=e.target.value.slice(0,16)||'Rook';$('#hudName').textContent=hero.name.toUpperCase()};$('#proportion').oninput=e=>{hero.scale=Number(e.target.value)/100;$('#proportionOut').value=e.target.value+'%';refreshHero()};
function setScreen(id){$$('.screen').forEach(s=>s.classList.remove('active'));if(id)$('#'+id).classList.add('active')}
function startEditor(){state='editor';setScreen('editorScreen');$('#hud').style.display='none';player.position.set(0,0,5);player.rotation.y=Math.PI;camera.position.set(10,6,12);camera.lookAt(0,1.4,5);refreshHero()}
function startWorld(){state='play';setScreen('');$('#hud').style.display='block';player.position.set(0,0,5);quest={id:'keeper',title:'A NAME IN THE DUST',text:'Speak with the keeper at Hearthside.',tag:'MAIN THREAD'};updateQuest();cameraAngle=0;showToast(`The Marches remember ${hero.name}.`);}
function updateQuest(){if(!quest)return;$('#questTitle').textContent=quest.title;$('#questText').textContent=quest.text;$('#questTag').textContent=quest.tag}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),2400)}
function talkTo(target){interactTarget=target;$('#dialogue').classList.add('open');const name=hero.name||'traveler';let title=target.userData.name,text='',actions=[];if(target===keeper){if(quest?.id==='keeper'){text=`“So you’re ${name}. The road has been asking after you.” The keeper eyes the ridge. “Take this little trouble off my hands, and I’ll tell you what waits beyond.”`;actions=[['Take the errand','accept']]}else if(quest?.id==='hunt'){text=`“Back already, ${name}? Those Ashlings trouble the road no more. A good start. The scout has a better lead.”`;actions=[['Claim reward','reward']]}else{text=`“The old crown is waking, ${name}. Find the scout north of the road. The Demon King’s shadow reaches farther each dusk.”`;actions=[['Ask about the crown','lore']]}}else if(target===scout){if(!bossUnlocked){text=`“${name}, six Ashlings have been seen near the old stones. Bring back three cores and I’ll mark the way to the Ashen Crown.”`;actions=[['I’ll find the cores','scout']]}else{text=`“The crown waits, ${name}. No more errands. The old keep is yours to face. Strike when its guard falls—and dodge the fire.”`;actions=[['Open the road','boss']]}}else{text=`“${name}! Keep your eyes on the ridge. Ashlings come and go, but the Demon King never leaves anything alone.”`;actions=[['Close','close']]}
$('#dialogueTitle').textContent=title;$('#dialogueText').textContent=text;const holder=$('#dialogueActions');holder.innerHTML='';actions.forEach(([label,action])=>{const b=document.createElement('button');b.className='btn'+(action==='accept'||action==='reward'||action==='boss'?' primary':'');b.textContent=label;b.onclick=()=>dialogueAction(action);holder.appendChild(b)});const close=document.createElement('button');close.className='btn';close.textContent='Leave';close.onclick=()=>$('#dialogue').classList.remove('open');holder.appendChild(close)}
function dialogueAction(action){$('#dialogue').classList.remove('open');if(action==='accept'){quest={id:'hunt',title:'ASH ON THE ROAD',text:'Defeat 3 Ashlings and gather their cores.',tag:'FIELD ERRAND'};updateQuest();showToast('Field errand accepted · 40 XP on completion.')}if(action==='scout'){quest={id:'cores',title:'THE ASHEN CROWN',text:'Gather 3 Ashling cores, then return to the scout.',tag:'SCOUT’S MARK'};updateQuest();showToast('The scout marked the old stones.')}if(action==='reward'){hero.coins+=18;hero.xp+=40;levelCheck();hero.inventory['Sunstone']=(hero.inventory['Sunstone']||0)+1;quest={id:'scout',title:'A CROWN IN THE DARK',text:'Find the scout beyond Hearthside.',tag:'MAIN THREAD'};updateQuest();showToast('+40 XP · +18 marks · Sunstone');}if(action==='boss'){if(!boss){boss=spawnEnemy(0,-95,true);bossUnlocked=true}quest={id:'boss',title:'THE ASHEN CROWN',text:'Defeat the Demon King.',tag:'FINAL ENCOUNTER'};updateQuest();$('#bossbar').classList.add('show');showToast('The Ashen Crown stirs.');}if(action==='lore')showToast('The Demon King was once a keeper of this land.');}
